CREATE DATABASE IF NOT EXISTS climatefoodordering;
USE climatefoodordering;
CREATE TABLE IF NOT EXISTS Customer(customer_id INT PRIMARY KEY AUTO_INCREMENT,customer_name VARCHAR(100) NOT NULL,phone_number VARCHAR(15),email VARCHAR(100));
CREATE TABLE IF NOT EXISTS Climate(climate_id INT PRIMARY KEY AUTO_INCREMENT,climate_name VARCHAR(30) NOT NULL UNIQUE,temperature_min INT,temperature_max INT,description VARCHAR(200));
CREATE TABLE IF NOT EXISTS Food(food_id INT PRIMARY KEY AUTO_INCREMENT,food_name VARCHAR(100) NOT NULL,category VARCHAR(50),price DECIMAL(10,2) NOT NULL,climate VARCHAR(30),availability VARCHAR(30) DEFAULT 'Available',description VARCHAR(255));
CREATE TABLE IF NOT EXISTS Cart(cart_id INT PRIMARY KEY AUTO_INCREMENT,customer_name VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Cart_Items(cart_item_id INT PRIMARY KEY AUTO_INCREMENT,cart_id INT NOT NULL,food_id INT NOT NULL,quantity INT NOT NULL DEFAULT 1,FOREIGN KEY(cart_id) REFERENCES Cart(cart_id) ON DELETE CASCADE,FOREIGN KEY(food_id) REFERENCES Food(food_id));
CREATE TABLE IF NOT EXISTS Orders(order_id INT PRIMARY KEY AUTO_INCREMENT,customer_id INT NOT NULL,climate_id INT NULL,total_amount DECIMAL(10,2) NOT NULL,payment_method VARCHAR(50),payment_status VARCHAR(50),order_status VARCHAR(50),order_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES Customer(customer_id),FOREIGN KEY(climate_id) REFERENCES Climate(climate_id));
CREATE TABLE IF NOT EXISTS Order_Items(order_item_id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,food_id INT NOT NULL,quantity INT NOT NULL,price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES Orders(order_id) ON DELETE CASCADE,FOREIGN KEY(food_id) REFERENCES Food(food_id));
CREATE TABLE IF NOT EXISTS Review(review_id INT PRIMARY KEY AUTO_INCREMENT,food_id INT NOT NULL,customer_name VARCHAR(100) NOT NULL,rating INT NOT NULL,review_text VARCHAR(500),review_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(food_id) REFERENCES Food(food_id) ON DELETE CASCADE);
INSERT INTO Customer(customer_name,phone_number) SELECT 'Demo Customer','9999999999' WHERE NOT EXISTS(SELECT 1 FROM Customer WHERE customer_name='Demo Customer');
